# are retained to record the searches that found no pairs.
# Regular graphs: Markus Meringer's database; Python conversion and pair
# calculations: Sammy Beasley. See REFERENCES.bib and the repository README.
# Pair indices are zero-based positions in the original graph lists. Thus
# notebook index 10 corresponds to source variable G_10_4_11 for (10, 4).
# Graph edges are defined once in the regular and strongly regular modules.

