def get_pairs(collection):
    """Return fresh (NetworkX graph, NetworkX graph) pairs in saved order."""
    if collection not in PAIR_INDICES:
        raise ValueError(f'Unknown pair collection: {collection}')
    if collection == '16v_srg':
        from strongly_regular_graphs import all_16v_srg_graphs
        return [(all_16v_srg_graphs[0].copy(), all_16v_srg_graphs[1].copy())]
    n, degree = map(int, re.fullmatch(r'(\d+)v_(\d+)reg', collection).groups())
    graphs = {index: get_graph(n, degree, index)
              for index in sorted({i for pair in PAIR_INDICES[collection] for i in pair})}
    return [(graphs[a].copy(), graphs[b].copy()) for a, b in PAIR_INDICES[collection]]


def __getattr__(name):
    match = re.fullmatch(r'cospectral_(.+)_(pairs|indices)', name)
    if match and match[1] in PAIR_INDICES:
        return get_pairs(match[1]) if match[2] == 'pairs' else PAIR_INDICES[match[1]].copy()
    raise AttributeError(f'module {__name__!r} has no attribute {name!r}')


__all__ = ['PAIR_INDICES', 'get_pairs'] + [
    f'cospectral_{collection}_{kind}'
    for collection in PAIR_INDICES for kind in ('pairs', 'indices')
]
